function forgot(){const e=$('#fe1').value.trim().toLowerCase(),p=$('#fp1').value.replace(/\s/g,''),u=db.users.find(x=>x.email==e);if(u&&u.role!='admin'&&u.phone.replace(/\s/g,'').slice(-8)==p.slice(-8)&&!db.resets.some(r=>r.uid==u.id&&r.status=='open'))db.resets.push({id:uid(),uid:u.id,email:e,phone:u.phone,t:Date.now(),status:'open'});save();toast('Request sent. The admin will contact you.');go('login')}
async function login() {
    const email = $('#le').value.trim().toLowerCase();
    const password = $('#lp').value;

    if (!email || !password) {
        return toast('Enter your email and password');
    }

    try {
        let response;
        let result;

        // Try ADMIN login first so the server creates
        // the authentication cookie required by admin APIs.
        response = await fetch('/api/Admin/login', {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                email: email,
                password: password
            })
        });

        result = await response.json().catch(() => ({}));

        let isAdmin = response.ok;

        // If this is not a valid admin login, try normal login.
        if (!isAdmin) {
            response = await fetch('/api/Account/login', {
                method: 'POST',
                credentials: 'same-origin',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    email: email,
                    password: password
                })
            });

            result = await response.json().catch(() => ({}));

            if (!response.ok) {
                return toast(
                    result.message || 'Wrong email or password'
                );
            }
        }

        me = {
            id: result.userId || result.id || null,
            name: result.fullName || result.name || '',
            fullName: result.fullName || result.name || '',
            email: result.email || email,
            role: result.role || '',
            status: result.status || 'Pending'
        };

        if (me.id !== null) {
            localStorage.setItem('aplme', me.id);
        }

        // Open the dashboard using the existing navigation.
        go('dash', { tab: '', sec: '' });
        if (me.role.toLowerCase() == 'admin') {
            await loadAdminPending();
            await loadAdminUsers();
            render();
        }

        // Load real pending accounts only after admin login.
        if (isAdmin) {
            const loaded = await loadAdminPending();
            render();

            if (!loaded) {
                console.error(
                    'Admin logged in, but pending approvals could not load.'
                );
            }
        }

    } catch (error) {
        console.error('Login error:', error);
        toast('Could not connect to the server. Please try again.');
    }
}


const pwCard=()=>`<div class="f"><h3>Change password</h3><div class="row"><div><label>Current password</label><input id="cp0" type="password"></div><div><label>New password</label><input id="cp1" type="password"></div><div><label>Confirm new password</label><input id="cp2" type="password"></div></div>${showPw(['cp0','cp1','cp2'])}<button class="btn" onclick="chpw()">Update password</button></div>`;
async function chpw(){if(await H(me.email+':'+$('#cp0').value)!=me.pw)return toast('Current password is wrong');const p=$('#cp1').value;if(!PW.test(p))return toast('New password too weak');if(p!=$('#cp2').value)return toast('Passwords do not match');me.pw=await H(me.email+':'+p);me.must=false;save();toast('Password updated');render()}
async function issue(id){const r=db.resets.find(x=>x.id==id),u=usr(r.uid),A='ABCDEFGHJKLMNPQRSTUVWXYZ',a='abcdefghijkmnpqrstuvwxyz',pk=(s,n)=>[...Array(n)].map(()=>s[rnd(s.length)]).join(''),tp=pk(A,3)+pk(a,4)+(10+rnd(89))+'#'+pk(A,1);u.pw=await H(u.email+':'+tp);u.must=true;r.status='done';save();render();prompt('Temporary password for '+u.name+'. Give it to them by phone after confirming who they are:',tp)}
const TERMS=()=>`<h3>AutoParts Link Botswana: User Agreement</h3><p><b>Please read this carefully. When you tick "I agree" and type your full name, you are signing a binding agreement with the platform operator.</b></p><ol style="padding-left:20px"><li><b>Who may register.</b> You must be at least 18 and legally able to enter a contract. You must register in your own name using your own valid Omang, Passport or Driving Licence. Using someone else's documents, or opening more than one account, is not allowed.</li><li><b>Identity verification.</b> You must upload a clear photo of your document. Our administrators review it by hand. Your document and its number are used only to verify your identity and prevent fraud. They are visible only to authorised administrators, are never shown on your profile or listings, and are kept only as long as needed for verification, security and legal duties. By uploading, you consent to this processing under applicable Botswana data-protection law.</li><li><b>Approval.</b> Your account stays at "Pending approval" until reviewed, then becomes "Approved" or "Rejected". We may refuse, suspend or remove any account, including for false or unclear documents.</li><li><b>Accurate information.</b> Everything you submit must be true and kept up to date. Providing false information or forged documents may lead to permanent removal and, where the law requires, a report to the authorities.</li><li><b>Sellers.</b> You must own the part or have the right to sell it. You may not list stolen, counterfeit, illegally imported or unsafe parts. Photos must show the actual item, and the condition, years used and price must be honest. Listings are reviewed before publication, and approval is not a guarantee of quality. You must mark items as sold when they sell.</li><li><b>Mechanics.</b> Your skills, experience and certifications must be genuine. The platform only lists you; it does not supervise or guarantee your work. Prices and terms are agreed directly with customers.</li><li><b>Buyers.</b> Inspect the part and confirm it fits before you pay. Meet in a safe public place. Requests for parts must be genuine.</li><li><b>Platform fee.</b> A fee of <b>${db.settings.fee}%</b> of the final sale price applies to every sale made through a listing or buyer connection on this platform. Sellers must report completed sales honestly and pay the fee to the operator by the method the operator tells them. Taking a sale off the platform after being introduced here to avoid the fee is a breach of this agreement and may lead to suspension and recovery of the fee. The rate may change; changes apply only to future sales after notice.</li><li><b>Payments.</b> You may arrange payment directly with the other user or use the in-platform checkout where available. Checkout payments are made with the method you choose, the platform fee is taken from the seller's proceeds, and the rest is paid out to the seller's chosen payout method. We never store full card numbers, CVV or PINs. The platform does not guarantee the quality of any part or repair and is not a party to any sale. Disputes are between the parties, although we may help at our discretion.</li><li><b>Conduct.</b> No fraud, harassment, spam, offensive comments or fake requests. Do not try to bypass the approval process.</li><li><b>Privacy.</b> Your name, phone number and location may be shown on your listings or mechanic profile so people can contact you. Passwords are stored in hashed form and never shared. Your ID document is never public.</li><li><b>Liability.</b> To the fullest extent allowed by law, the operator is not liable for loss, injury, fraud by users, defective parts or poor workmanship arising from dealings between users.</li><li><b>Changes and closing your account.</b> We may update this agreement, and continued use means you accept the update. You may ask the admin to close your account at any time.</li><li><b>Governing law.</b> The laws of the Republic of Botswana apply.</li></ol>`;
