async function s1() {
    const email = G('re').trim().toLowerCase();
    const password = $('#rw').value;
    const name = G('rn').trim();
    const phone = G('rp');

    if (!name || !email || !phone || !password) {
        return toast('Fill all fields');
    }

    const pv = validateBotswanaMobile(phone);

    if (!pv.valid) {
        return toast(pv.message);
    }

    if (!/^\S+@\S+\.\S+$/.test(email)) {
        return toast('Enter a valid email');
    }

    if (!PW.test(password)) {
        return toast('Password too weak');
    }

    if (password !== $('#rw2').value) {
        return toast('Passwords do not match');
    }

    // Keep the original password temporarily so it can be
    // sent securely over HTTPS to the ASP.NET Core backend.
    Object.assign(R.d, {
        role: G('rr'),
        name: name,
        email: email,
        ph: phone.replace(/[\s-]/g, '').slice(-8),
        password: password
    });

    R.code = String(1000 + rnd(9000));
    R.s = 2;
    render();
}
