function s4(){if(!$('#ragree').checked||G('rsig').toLowerCase()!=R.d.name.toLowerCase())return toast('Tick the agreement and type your full name exactly as entered');R.d.agreedAt=Date.now();NS()==4?submit({}):(R.s=5,render())}
function s5(){const m=collectPay();if(!m)return;if(!Object.keys(m).length)return toast('Select at least one payment method');submit(m)}
async function submit(m) {
    const d = R.d;

    if (!d || !d.name || !d.email || !d.password) {
        return toast('Registration details are missing. Please register again.');
    }

    try {
        const response = await fetch('/api/Account/register', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                fullName: d.name,
                email: d.email,
                password: d.password,
                role: d.role,
                phoneNumber: '+267' + d.ph
            })
        });

        const result = await response.json();

        if (!response.ok) {
            return toast(
                result.message || 'Registration failed. Please try again.'
            );
        }

        // Registration is now saved in the ASP.NET Core database.
        // The administrator can approve the account there.
        d.password = '';
        R.s = 9;
        render();

    } catch (error) {
        console.error('Registration error:', error);
        toast('Could not connect to the server. Please try again.');
    }
}
