const PMX={om:{n:'Orange Money',i:'om',c:'#ff7900',t:'w'},smega:{n:'Smega (btc)',i:'btc',c:'#1ea84b',t:'w'},myzaka:{n:'MyZaka (Mascom)',i:'masc',c:'#f5c400',t:'w'},fnb:{n:'FNB',i:'fnb',c:'#009a9a',t:'b'},absa:{n:'Absa Botswana',i:'absa',c:'#e2001a',t:'b'},stb:{n:'Stanbic Bank',i:'stan',c:'#0033a0',t:'b'}};
