const luhn=n=>{let s=0,d=0;for(let i=n.length-1;i>=0;i--){let x=+n[i];if(d++%2){x*=2;if(x>9)x-=9}s+=x}return s%10==0};
function cardCheck(n){if(!/^\d+$/.test(n))return'card number must contain digits only.';const c=CT.find(c=>c[1].test(n));if(c&&!c[2].includes(n.length))return c[0]+' cards have '+c[2].join(', ')+' digits.';if(!c&&(n.length<12||n.length>19))return'enter a valid card number (12 to 19 digits).';return luhn(n)?'':'this card number is not valid. Please check it.'}
function fmtC(el){const d=el.value.replace(/\D/g,'').slice(0,19),b=brand(d);el.value=b=='American Express'?d.replace(/^(\d{0,4})(\d{0,6})(\d{0,5}).*/,'$1 $2 $3').trim():d.replace(/(.{4})/g,'$1 ').trim();el.nextElementSibling.textContent=b}
function validateOmang(omang,sex){if(!/^\d{9}$/.test(omang))return{valid:false,message:'Omang must contain exactly 9 digits.'};if(sex!=='male'&&sex!=='female')return{valid:false,message:'Select the sex shown on your Omang.'};const f=omang[4];if(sex==='male'&&f!=='1')return{valid:false,message:'The fifth digit must be 1 for male.'};if(sex==='female'&&f!=='2')return{valid:false,message:'The fifth digit must be 2 for female.'};return{valid:true,message:'Omang format accepted.'}}
