function collectPay(){const m={};for(const k of P){const o=PMX[k],v=i=>(($('#'+k+'_'+i))||{value:''}).value.trim();if(o.t=='w'){const n=v('n').replace(/\D/g,'');if(!/^7\d{7}$/.test(n))return fail(o.n+' number must start with 7 and have 8 digits');m[k]={mode:'num',number:n}}else{const c=v('c').replace(/\s/g,'');if(!v('h'))return fail('Enter the card holder name for '+o.n);{const e=cardCheck(c);if(e)return fail(o.n+': '+e)}{const x=v('e').match(/^(\d\d) \/ (\d\d)$/);if(!x||+x[1]<1||+x[1]>12||new Date(2000+ +x[2],+x[1])<new Date())return fail('Enter a valid, unexpired expiry date for '+o.n)}m[k]={card:{holder:v('h').toUpperCase(),last4:c.slice(-4),exp:v('e'),brand:brand(c)}}}}return m}
