V.dash = () => {
    if (!me) return V.login();

    me = db.users.find(u => u.id == me.id) || me;

    let h = `<h2>${esc(me.name)} <small>${me.status ? stat(me.status) : ''} <span class="tag">${me.role}</span></small></h2>`;

    if (me.role !== 'admin' && me.status !== 'Approved') {
        return h + `<div class="note">${me.status === 'Rejected'
                ? 'Your registration was rejected. Contact the admin.'
                : 'Your registration is pending approval. You will be able to use your dashboard once an admin approves it.'
            }</div>`;
    }

    return h
        + (me.must
            ? '<div class="note">You are using a temporary password. Please set a new one below.</div>'
            : '')
        + seg()
        + (
            S.sec === 'pay' && (me.role === 'buyer' || me.role === 'seller')
                ? walletCard()
                : S.sec === 'sec'
                    ? pwCard()
                    : V['d_' + me.role]() + (me.role === 'buyer' ? purch() : '')
        );
};
const tabs=(a,d)=>(S.tab=S.tab||d,`<div class="tabs">${a.map(x=>`<button class="${S.tab==x[0]?'on':''}" onclick="S.tab='${x[0]}';render()">${x[1]}</button>`).join('')}</div>`);
function lf(adm){return`<div class="f"><h3>${adm?'Add a listing (published instantly)':'Add a listing'}</h3><label>Photos (1–5)</label><input type="file" id="lm" accept="image/*" multiple><div class="row"><div><label>Part name</label><input id="l1"></div><div><label>Category (default section)</label>${sel('l2',db.cats.map(c=>[c.id,c.name]),'Choose')}</div><div><label>Vehicle make</label><input id="l3"></div><div><label>Model</label><input id="l4"></div><div><label>Year</label><input id="l5" type="number"></div><div><label>Part number</label><input id="l6"></div><div><label>Condition</label><select id="l7"><option>Used</option><option>New</option></select></div><div><label>Years used</label><input id="l8" type="number"></div><div><label>Price (BWP)</label><input id="l9" type="number"></div><div><label>Location</label><input id="l10"></div><div><label>Phone</label><input id="l11" value="${esc(me.phone)}"></div></div><br><button class="btn" onclick="addL(${adm})">Submit</button></div>`}
async function addL(adm){const v=i=>$('#'+i).value.trim();if(!v('l1')||!v('l2')||!v('l9'))return toast('Part name, category and price are required');let im=await files('#lm');if(!im.length)im=['k:'+v('l2')].filter(x=>IMG[x.slice(2)]);if(!im.length)return toast('Add at least one photo');
db.listings.push({id:uid(),sellerId:me.id,title:v('l1'),cat:v('l2'),make:v('l3'),model:v('l4'),year:v('l5'),partNo:v('l6'),cond:v('l7'),yearsUsed:v('l8'),price:+v('l9'),loc:v('l10'),phone:v('l11'),imgs:im,status:adm?'approved':'pending',comments:[],t:Date.now()});save();toast(adm?'Published':'Submitted for admin approval');S.tab='my';render()}
V.d_seller=()=>{const my=db.listings.filter(l=>l.sellerId==me.id);return tabs([['my','My listings'],['add','Add listing'],['tx','Sales']],'my')+(S.tab=='add'?lf(0):S.tab=='tx'?T(['Item','Price','Fee','Status'],db.txs.filter(t=>t.sellerId==me.id).map(t=>`<tr><td>${esc(t.title)}</td><td>${bwp(t.price)}</td><td>${bwp(t.fee)} (${t.rate}%)</td><td>${stat(t.status)}</td></tr>`)):T(['Listing','Price','Status',''],my.map(l=>`<tr><td>${esc(l.title)}</td><td>${bwp(l.price)}</td><td>${stat(l.status)}</td><td>${l.status=='approved'?`<button class="btn s" onclick="sold('${l.id}')">Mark sold</button> `:''}<button class="btn s d" onclick="delL('${l.id}')">Delete</button></td></tr>`)))};
function sold(id){const l=db.listings.find(x=>x.id==id),p=+prompt(`Final sale price in BWP?\nPlatform fee will be ${db.settings.fee}% — you arrange payment directly with the buyer.`,l.price);if(!p)return;const f=p*db.settings.fee/100;if(!confirm(`Report sale of ${bwp(p)}? Platform fee due: ${bwp(f)} (${db.settings.fee}%)`))return;l.status='sold';db.txs.push({id:uid(),listingId:id,title:l.title,sellerId:l.sellerId,price:p,rate:db.settings.fee,fee:f,t:Date.now(),status:'reported'});save();render()}
function delL(id){if(confirm('Delete listing?')){db.listings=db.listings.filter(l=>l.id!=id);save();render()}}
V.d_buyer=()=>{const my=db.reqs.filter(r=>r.buyerId==me.id);return`<div class="note">Post requests on the <a href="#" onclick="go('reqs');return false">Requests</a> page and manage seller responses below.</div>`+(my.map(r=>`<div class="f"><b>${esc(r.text)}</b>${r.responses.map((x,i)=>`<div class="cm">${esc(x.name)} ${stat(x.status)}<br>${esc(x.text)} · ${esc(x.phone)} ${x.status=='open'?`<br><button class="btn s" onclick="rr('${r.id}',${i},'accepted')">Accept</button> <button class="btn s d" onclick="rr('${r.id}',${i},'rejected')">Reject</button>`:''}</div>`).join('')||'<br><small style="color:var(--m)">No responses yet.</small>'}</div>`).join('')||'<p style="color:var(--m)">You have no requests yet.</p>')};
function rr(id,i,s){db.reqs.find(r=>r.id==id).responses[i].status=s;save();render()}
V.d_mechanic = () => `<div class="f"><h3>Your public profile</h3><p>${esc(me.area)} · ${esc(me.exp)} yrs<br>Skills: ${esc(me.skills)}<br>Services: ${esc(me.services)}</p><button class="btn g" onclick="editM()">Edit profile</button></div>`;

async function loadAdminPending() {
    try {
        const response = await fetch('/api/Admin/pending', {
            method: 'GET',
            credentials: 'same-origin'
        });

        if (!response.ok) {
            console.error(
                'Could not load pending accounts:',
                response.status
            );

            toast(response.status === 401 || response.status === 403
                ? 'Admin session expired. Please log in again.'
                : 'Could not load pending accounts.');

            return false;
        }

        const accounts = await response.json();

        if (!Array.isArray(accounts)) {
            console.error('Unexpected pending accounts response:', accounts);
            return false;
        }

        adminPending = accounts;
        return true;
    } catch (error) {
        console.error('Loading pending accounts failed:', error);
        toast('Could not connect to the server.');
        return false;
    }
}

async function loadAdminUsers() {
    const r = await fetch('/api/Admin/users', { credentials: 'same-origin' });
    if (r.ok) {
        db.users = (await r.json()).map(u => ({
            id: String(u.id),
            name: u.fullName,
            email: u.email,
            role: u.role,
            status: u.status,
            phone: u.phoneNumber
        }));
    }
}
async function deleteSelectedUsers() {
    const ids = [...new Set(
        (S.selectedUsers || [])
            .map(id => Number(id))
            .filter(id => Number.isInteger(id) && id > 0)
    )];

    if (ids.length === 0) {
        return toast('Select at least one user to delete.');
    }

    if (!confirm(
        `Permanently delete ${ids.length} selected account(s)? This cannot be undone.`
    )) {
        return;
    }

    try {
        const response = await fetch('/api/Admin/users/delete', {
            method: 'POST',
            credentials: 'same-origin',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ ids: ids })
        });

        const result = await response.json().catch(() => ({}));

        if (!response.ok) {
            toast(result.message || 'Could not delete the selected accounts.');
            return;
        }

        S.selectedUsers = [];

        await loadAdminUsers();
        render();

        toast(result.message || 'Selected accounts deleted successfully.');
    } catch (error) {
        console.error('Delete users failed:', error);
        toast('Could not connect to the server. Please try again.');
    }
}
async function reviewAccount(id, action) {
    if (!['approve', 'reject'].includes(action)) {
        return;
    }

    try {
        const response = await fetch(
            `/api/Admin/${action}/${id}`,
            {
                method: 'POST',
                credentials: 'same-origin'
            }
        );

        const result = await response.json().catch(() => ({}));

        if (!response.ok) {
            toast(result.message || `Could not ${action} account.`);
            return;
        }

        toast(result.message || 'Account updated successfully.');

        await loadAdminPending();
        await loadAdminUsers();
        render();
    } catch (error) {
        console.error('Account review failed:', error);
        toast('Could not connect to the server.');
    }
}

function editM(){const f=(k,l)=>{const v=prompt(l,me[k]||'');if(v!==null)me[k]=v};f('area','Area');f('exp','Years of experience');f('skills','Skills');f('services','Services');f('certs','Certifications');save();render()}
V.d_admin = () => {
    const pending = Array.isArray(adminPending) ? adminPending : [];
    const pu = pending.length;
    const pl = db.listings.filter(l => l.status == 'pending').length;

    let h = tabs([
        ['ov', 'Overview'],
        ['ap', `Approvals (${pu})`],
        ['li', `Listings (${pl})`],
        ['add', 'Add listing'],
        ['cat', 'Categories'],
        ['us', 'Users'],
        ['rs', `Password resets (${db.resets.filter(r => r.status == 'open').length})`],
        ['rq', 'Requests'],
        ['rp', 'Reports'],
        ['tx', 'Transactions'],
        ['set', 'Settings']
    ], 'ov'), t = S.tab;

    if (t == 'ov') {
        const U = db.users,
            c = r => U.filter(u => u.role == r && u.status == 'Approved').length,
            L = db.listings,
            sum = db.txs.reduce((a, x) => a + x.fee, 0);

        h += `<div class="stats">${[
                [pu, 'Accounts awaiting approval'],
                [pl, 'Listings awaiting approval'],
                [L.filter(l => l.status == 'approved').length, 'Live listings'],
                [L.filter(l => l.status == 'sold').length, 'Items sold'],
                [c('buyer'), 'Approved buyers'],
                [c('seller'), 'Approved sellers'],
                [c('mechanic'), 'Approved mechanics'],
                [db.reports.length, 'Reports'],
                [db.txs.length, 'Transactions'],
                [bwp(sum), 'Commission recorded']
            ].map(a => `<div><b>${a[0]}</b><span>${a[1]}</span></div>`).join('')
            }</div>`;
    }

    // APPROVALS: Read real pending registrations from the API
    if (t == 'ap') {
        h += T(
            ['Name', 'Role', 'Contact', 'ID document', ''],
            pending.map(u => {
                const id = u.id;
                const name = u.name || u.fullName || u.fullname || 'N/A';
                const email = u.email || 'N/A';
                const phone = u.phone || u.phoneNumber || 'N/A';
                const status = u.status || 'Pending';
                const idType = u.idType || 'n/a';
                const docNo = u.docNo || u.omang || '';
                const idImg = u.idImg || u.idImage;

                return `<tr>
                    <td>${esc(name)}</td>
                    <td>${esc(u.role || 'N/A')}</td>
                    <td>${esc(email)}<br>${esc(phone)}</td>
                    <td>
                        ${esc(idType)} ${esc(docNo)}
                        ${idImg ? `<br><button class="btn s g" onclick="viewId('${id}')">View ID</button>` : ''}
                    </td>
                    <td>
                        ${String(status).toLowerCase() == 'pending'
                        ? `<button class="btn s" onclick="reviewAccount('${id}', 'approve')">Approve</button>
                               <button class="btn s d" onclick="reviewAccount('${id}', 'reject')">Reject</button>`
                        : esc(status)}
                    </td>
                </tr>`;
            })
        );
    }

    if (t == 'rs') h += T(
        ['User', 'Phone', 'Requested', ''],
        db.resets.filter(r => r.status == 'open').map(r =>
            `<tr>
                <td>${esc(usr(r.uid).name)}<br>${esc(r.email)}</td>
                <td>${esc(r.phone)}</td>
                <td>${new Date(r.t).toLocaleString()}</td>
                <td><button class="btn s" onclick="issue('${r.id}')">Issue temporary password</button></td>
            </tr>`
        )
    );

    if (t == 'li') h += T(
        ['Listing', 'Seller', 'Price', 'Status', ''],
        db.listings.map(l =>
            `<tr>
                <td><a href="#" onclick="openL('${l.id}');return false">${esc(l.title)}</a></td>
                <td>${esc(usr(l.sellerId).name)}</td>
                <td>${bwp(l.price)}</td>
                <td>${stat(l.status)}</td>
                <td>
                    ${l.status == 'pending'
                ? `<button class="btn s" onclick="ls('${l.id}','approved')">Approve</button>
                           <button class="btn s d" onclick="ls('${l.id}','rejected')">Reject</button>`
                : ''}
                    <button class="btn s d" onclick="delL('${l.id}')">Delete</button>
                </td>
            </tr>`
        )
    );

    if (t == 'add') h += lf(1);

    if (t == 'cat') h += `
        <div class="f">
            <h3>Add a default category (sellers list under these)</h3>
            <div class="row">
                <div><label>Name</label><input id="cn"></div>
                <div><label>Image</label><input type="file" id="ci" accept="image/*"></div>
            </div>
            <br><button class="btn" onclick="addCat()">Add category</button>
        </div>
        <div class="grid">${db.cats.map(c =>
        `<div class="card">
                    <img src="${src(c.img)}">
                    <div class="p">${esc(c.name)}
                        <button class="btn s d" onclick="db.cats=db.cats.filter(x=>x.id!='${c.id}');save();render()">Remove</button>
                    </div>
                </div>`
    ).join('')
        }</div>`;

    if (t == 'us') {
        const users = db.users;
        const search = (S.userSearch || '').toLowerCase();
        const roleFilter = S.userRole || 'all';
        const statusFilter = S.userStatus || 'all';
        const selected = S.selectedUsers || [];

        const filteredUsers = users.filter(u => {
            const text = `${u.name || u.fullName || ''} ${u.email || ''} ${u.phone || u.phoneNumber || ''}`.toLowerCase();

            return text.includes(search) &&
                (roleFilter === 'all' || u.role === roleFilter) &&
                (statusFilter === 'all' || String(u.status).toLowerCase() === statusFilter.toLowerCase());
        });

        h += `
        <div class="f">
            <h3>Manage Users (${users.length})</h3>

            <label>Search users</label>
            <input id="userSearch" placeholder="Search name, email or phone..."
                value="${esc(S.userSearch || '')}"
                oninput="S.userSearch=this.value;render()">

            <div class="row">
                <div>
                    <label>Role</label>
                    <select onchange="S.userRole=this.value;render()">
                        <option value="all">All roles</option>
                        <option value="admin" ${roleFilter === 'admin' ? 'selected' : ''}>Admin</option>
                        <option value="seller" ${roleFilter === 'seller' ? 'selected' : ''}>Seller</option>
                        <option value="buyer" ${roleFilter === 'buyer' ? 'selected' : ''}>Buyer</option>
                        <option value="mechanic" ${roleFilter === 'mechanic' ? 'selected' : ''}>Mechanic</option>
                    </select>
                </div>
                <div>
                    <label>Status</label>
                    <select onchange="S.userStatus=this.value;render()">
                        <option value="all">All statuses</option>
                        <option value="Approved" ${statusFilter === 'approved' ? 'selected' : ''}>Approved</option>
                        <option value="Pending" ${statusFilter === 'pending' ? 'selected' : ''}>Pending</option>
                        <option value="Rejected" ${statusFilter === 'rejected' ? 'selected' : ''}>Suspended / Rejected</option>
                    </select>
                </div>
            </div>

            <br>
            <button class="btn d"
                  onclick="deleteSelectedUsers()"
                  ${selected.length === 0 ? 'disabled' : ''}>
                  Delete Selected (${selected.length})
             </button>
        </div>
    `;

        h += T(
            ['<input type="checkbox" onchange="S.selectedUsers=this.checked?[' +
                filteredUsers.filter(u => u.role !== 'admin').map(u => `'${String(u.id).replace(/'/g, "\\'")}'`).join(',') +
                ']:[];render()">', 'Name', 'Role', 'Email', 'Status', ''],
            filteredUsers.map(u => `
            <tr>
                <td>
                    ${u.role !== 'admin'
                    ? `<input type="checkbox"
                            ${selected.includes(String(u.id)) ? 'checked' : ''}
                            onchange="S.selectedUsers=this.checked?[...(S.selectedUsers||[]),'${String(u.id).replace(/'/g, "\\'")}']:(S.selectedUsers||[]).filter(id=>id!=='${String(u.id).replace(/'/g, "\\'")}');render()">`
                    : ''}
                </td>
                <td>${esc(u.name || u.fullName || 'N/A')}</td>
                <td>${esc(u.role || 'N/A')}</td>
                <td>${esc(u.email || 'N/A')}</td>
                <td>${stat(u.status)}</td>
                <td>
                    ${u.idImg ? `<button class="btn s g" onclick="viewId('${u.id}')">ID</button>` : ''}
                    ${u.role !== 'admin'
                    ? `<button class="btn s" onclick="us('${u.id}','Approved')">Approve</button>
                           <button class="btn s d" onclick="us('${u.id}','Rejected')">Suspend</button>`
                    : ''}
                </td>
            </tr>
        `)
        );
    }
    if (t == 'rq') h += T(
        ['Request', 'Buyer', 'Responses'],
        db.reqs.map(r =>
            `<tr>
                <td>${esc(r.text)}</td>
                <td>${esc(usr(r.buyerId).name)}</td>
                <td>${r.responses.length}</td>
            </tr>`
        )
    );

    if (t == 'rp') h += T(
        ['Listing', 'By', 'Reason'],
        db.reports.map(r =>
            `<tr>
                <td><a href="#" onclick="openL('${r.listingId}');return false">view</a></td>
                <td>${esc(r.by)}</td>
                <td>${esc(r.reason)}</td>
            </tr>`
        )
    );

    if (t == 'tx') {
        const sum = db.txs.reduce((a, x) => a + x.fee, 0),
            conf = db.txs.filter(x => x.status == 'confirmed').reduce((a, x) => a + x.fee, 0);

        h += `<div class="note">
            Estimated commission on reported sales: <b>${bwp(sum)}</b> ·
            Confirmed: <b>${bwp(conf)}</b>.
            Fees are calculated at the platform rate on each recorded sale.
        </div>` + T(
            ['Item', 'Seller', 'Price', 'Fee', 'Status', ''],
            db.txs.map(x =>
                `<tr>
                    <td>
                        ${esc(x.title)}
                        ${x.method
                    ? `<br><small style="color:var(--m)">Paid by ${esc(usr(x.buyerId).name)} via ${pm(x.method)[1]} · ${x.ref}</small>`
                    : ''}
                    </td>
                    <td>${esc(usr(x.sellerId).name)}</td>
                    <td>${bwp(x.price)}</td>
                    <td>${bwp(x.fee)} (${x.rate}%)</td>
                    <td>${stat(x.status)}</td>
                    <td>
                        ${x.status == 'reported'
                    ? `<button class="btn s" onclick="db.txs.find(t=>t.id=='${x.id}').status='confirmed';save();render()">Confirm</button>`
                    : ''}
                    </td>
                </tr>`
            )
        );
    }

    if (t == 'set') h += `
        <div class="f">
            <h3>Platform fee</h3>
            <select id="fe">
                <option value="4" ${db.settings.fee == 4 ? 'selected' : ''}>4%</option>
                <option value="5" ${db.settings.fee == 5 ? 'selected' : ''}>5%</option>
            </select>
            <br><br>
            <button class="btn" onclick="db.settings.fee=+$('#fe').value;save();toast('Fee updated')">Save</button>
            <p class="note">
                Examples at ${db.settings.fee}%:
                BWP 500 → ${bwp(500 * db.settings.fee / 100)} ·
                BWP 1,000 → ${bwp(1000 * db.settings.fee / 100)} ·
                BWP 2,500 → ${bwp(2500 * db.settings.fee / 100)}
            </p>
            <button class="btn d" onclick="if(confirm('Reset ALL data in this browser?')){localStorage.removeItem('apl');location.reload()}">Reset all data</button>
        </div>`;

    return h;
};
function us(id,s){db.users.find(u=>u.id==id).status=s;save();render()}
function ls(id,s){db.listings.find(l=>l.id==id).status=s;save();render()}
async function addCat(){const n=$('#cn').value.trim(),im=await files('#ci');if(!n||!im[0])return toast('Name and image required');db.cats.push({id:uid(),name:n,img:im[0]});save();render()}
function render(){nav();$('#app').innerHTML=V[S.v]();$('#ft').innerHTML=foot()}
render();
